let tenants=[],editingId=-1;const loadTenants=()=>{$("#tenantTable").hide(),$("#loading").show(),api.tenants.get().success(t=>{tenants=t,$("#loading").hide(),$("#tenantTable").show();const e=$("#tenantTable").DataTable({destroy:!0,columnDefs:[{orderable:!1,targets:"no-sort"}]});e.clear(),$.each(tenants,(a,n)=>{e.row.add([escapeHtml(n.name),moment(n.created_at).format("MMMM Do YYYY, h:mm:ss a"),"<div class='pull-right' style='white-space:nowrap'><button class='btn btn-primary edit-button' data-tenant-id='"+n.id+"'><i class='fa fa-pencil'></i></button> <button class='btn btn-danger delete-button' data-tenant-id='"+n.id+"'><i class='fa fa-trash-o'></i></button></div>"])}),e.draw()}).error(()=>errorFlash("Error fetching tenants"))},saveTenant=()=>{const t=$("#name").val();editingId===-1?api.tenants.post({name:t}).success(()=>{successFlash("Tenant created"),$("#modal").modal("hide"),loadTenants()}).error(e=>modalError(e.responseJSON.message)):api.tenantId.put({id:editingId,name:t}).success(()=>{successFlash("Tenant updated"),$("#modal").modal("hide"),loadTenants()}).error(e=>modalError(e.responseJSON.message))},editTenant=t=>{if(editingId=t,$("#modal\\.flashes").empty(),t===-1)$("#tenantModalLabel").text("New Tenant"),$("#name").val("");else{const e=tenants.find(a=>a.id===t);$("#tenantModalLabel").text("Edit Tenant"),$("#name").val(e?e.name:"")}$("#modal").modal("show")},deleteTenant=t=>{const e=tenants.find(a=>a.id===t);Swal.fire({title:"Are you sure?",text:"Delete the tenant "+escapeHtml(e.name)+"? Its users and teams must be removed first.",type:"warning",showCancelButton:!0,confirmButtonText:"Delete",confirmButtonColor:"#428bca",reverseButtons:!0,preConfirm:()=>new Promise((a,n)=>{api.tenantId.delete(t).success(()=>a()).error(s=>n(s.responseJSON.message))}).catch(a=>Swal.showValidationMessage(a))}).then(a=>{a.value&&(Swal.fire("Tenant Deleted!","","success"),loadTenants())})};$(document).ready(function(){loadTenants(),$("#new_button").click(()=>editTenant(-1)),$("#modalSubmit").click(saveTenant),$("#tenantTable").on("click",".edit-button",function(){editTenant(parseInt($(this).attr("data-tenant-id"),10))}),$("#tenantTable").on("click",".delete-button",function(){deleteTenant(parseInt($(this).attr("data-tenant-id"),10))})});
